// audio-sound: a chime on a sim event
//
// Shows: `sounds` maps a sim event to a sound. The first tap or key unlocks audio (browsers allow
//   sound only after a gesture); from then on each Chime event the sim emits plays chime.wav.
// Controls: tap or press any key to unlock sound
// Packages: @mcthaydt/automata, zod
// Difficulty: ★☆☆☆
// Tier: core
// Golden: 180
import {
  defineComponent,
  defineEvent,
  defineGame,
  definePlugin,
  defineSystem,
  rect,
} from '@mcthaydt/automata'
import { z } from 'zod'

// A synthesized chime (resources/sounds/PROVENANCE.md).
const chime = new URL('../resources/sounds/chime.wav', import.meta.url).href

const Bell = defineComponent('bell', { x: 'f32', y: 'f32', angle: 'f32' })
const Chime = defineEvent('chime', z.object({}))

// The bell rings once a second (every 60 ticks) and swings back to rest in between.
const ring = defineSystem('ring', (ctx) => {
  const ringing = ctx.tick % 60 === 0
  if (ringing) ctx.emit(Chime, {})
  for (const bell of ctx.query(Bell)) {
    const { angle } = bell.get(Bell)
    bell.set(Bell, { angle: ringing ? 0.6 : angle * 0.9 })
  }
})

const bells = definePlugin({ name: 'bells', defs: [Bell, Chime, ring] })

export default defineGame({
  id: 'audio-sound',
  size: { width: 320, height: 180 },
  sim: {
    plugins: [bells],
    seed: 1,
    setup: (sim) => {
      sim.spawn([[Bell, { x: 160, y: 90, angle: 0 }]])
    },
  },
  views: { [Bell.id]: rect({ w: 32, h: 40, color: 0xffc825, anchor: { x: 0.5, y: 0 } }) },
  sounds: { [Chime.id]: chime },
})

// core-basic-window: open a game window
//
// Shows: defineGame() needs only an id, a size and a sim; startGame() fills in the rest: the host, the
//   renderer, and the title, play and paused screens.
// Controls: none
// Packages: @mcthaydt/automata
// Difficulty: ★☆☆☆
// Tier: core
import { defineGame } from '@mcthaydt/automata'

export default defineGame({
  id: 'core-basic-window',
  size: { width: 320, height: 180 },
  sim: { plugins: [] },
})

// core-camera-2d: a camera that follows a square around a world bigger than the screen
//
// Shows: createCamera2d() follows a target with a dead zone, stays inside the world's bounds and shakes on a bump;
//   it moves the world container only, so the sim's positions are untouched.
// Controls: arrows or WASD
// Packages: @mcthaydt/automata, zod
// Difficulty: ★★☆☆
// Tier: core
import {
  createCamera2d,
  defineCommand,
  defineComponent,
  defineGame,
  definePlugin,
  defineSystem,
  keys,
  rect,
} from '@mcthaydt/automata'
import { z } from 'zod'

const VIEW = { width: 320, height: 180 }
const WORLD = { x: 0, y: 0, width: 960, height: 540 }
const HALF = 4

const Body = defineComponent('body', { x: 'f32', y: 'f32' })
const Marker = defineComponent('marker', { x: 'f32', y: 'f32' })
const step = z.number().int().min(-1).max(1).default(0)
const Move = defineCommand('move', z.object({ x: step, y: step }))

// The sim keeps the square inside the world; the camera only decides which part of the world is on screen.
const move = defineSystem('move', (ctx) => {
  for (const { payload } of ctx.commands.of(Move))
    for (const body of ctx.query(Body)) {
      const { x, y } = body.get(Body)
      body.set(Body, {
        x: Math.min(Math.max(x + payload.x * 3, HALF), WORLD.width - HALF),
        y: Math.min(Math.max(y + payload.y * 3, HALF), WORLD.height - HALF),
      })
    }
})

const world = definePlugin({ name: 'world', defs: [Body, Marker, Move, move] })

// The camera follows what is drawn, so it reads the square's interpolated view rather than the sim.
let squareView: { readonly position: { readonly x: number; readonly y: number } } | undefined
const drawSquare = rect({ w: HALF * 2, h: HALF * 2, color: 0xffc825 })
const trackSquare: typeof drawSquare = (row, componentId) => {
  const view = drawSquare(row, componentId)
  squareView = view?.container
  return view
}

const atEdge = (x: number, y: number): boolean =>
  x <= HALF || y <= HALF || x >= WORLD.width - HALF || y >= WORLD.height - HALF

export default defineGame({
  id: 'core-camera-2d',
  size: VIEW,
  sim: {
    plugins: [world],
    seed: 1,
    setup: (sim) => {
      // A grid of floor markers, so the camera's movement shows.
      for (let x = 40; x < WORLD.width; x += 80)
        for (let y = 45; y < WORLD.height; y += 90) sim.spawn([[Marker, { x, y }]])
      sim.spawn([[Body, { x: 480, y: 270 }]])
    },
  },
  input: keys(Move, {
    ArrowLeft: { x: -1 },
    KeyA: { x: -1 },
    ArrowRight: { x: 1 },
    KeyD: { x: 1 },
    ArrowUp: { y: -1 },
    KeyW: { y: -1 },
    ArrowDown: { y: 1 },
    KeyS: { y: 1 },
  }),
  views: { [Marker.id]: rect({ w: 6, h: 6, color: 0x3e3546 }), [Body.id]: trackSquare },
  renderer: {
    setup: (stage) => {
      const camera = createCamera2d(stage.world, {
        view: VIEW,
        follow: { rate: 8, deadZone: { width: 64, height: 36 } },
        bounds: WORLD,
      })
      let wasAtEdge = false
      return {
        draw: (frame) => {
          if (squareView === undefined) return
          const { x, y } = squareView.position
          // A small bump each time the square reaches the world's edge.
          if (atEdge(x, y) && !wasAtEdge) camera.shake(0.6)
          wasAtEdge = atEdge(x, y)
          camera.target(x, y)
          camera.update(frame.frameMs / 1000)
        },
      }
    },
  },
})

// core-host-lifecycle: the sim stands still while the host has the game in the background
//
// Shows: the game package handles the host's lifecycle for a game, so nothing here mentions the host. The page
//   draws nothing until the host says ready; when the host sends the game to the background (its drawer, an ad,
//   a hidden tab) the runtime stops the sim and opens the pause screen, and Resume plays on from the same tick.
//   The HUD counts the sim's ticks and says whether the frame is paused.
// Controls: none; switch to another tab (or open the host's drawer) and come back
// Packages: @mcthaydt/automata
// Difficulty: ★☆☆☆
// Tier: core
import { defineComponent, defineGame, definePlugin, defineSystem, rect } from '@mcthaydt/automata'

const Pacer = defineComponent('pacer', { x: 'f32', y: 'f32', vx: 'f32' })

// A square that paces the field, so a stopped sim is a frozen square as well as a frozen count.
const pace = defineSystem('pace', (ctx) => {
  for (const pacer of ctx.query(Pacer)) {
    const { x, y, vx } = pacer.get(Pacer)
    const next = x + vx < 8 || x + vx > 312 ? -vx : vx
    pacer.set(Pacer, { x: x + next, y, vx: next })
  }
})

const pacing = definePlugin({ name: 'pacing', defs: [Pacer, pace] })

export default defineGame({
  id: 'core-host-lifecycle',
  size: { width: 320, height: 180 },
  sim: {
    plugins: [pacing],
    seed: 1,
    setup: (sim) => void sim.spawn([[Pacer, { x: 8, y: 90, vx: 1.5 }]]),
  },
  views: { [Pacer.id]: rect({ w: 12, h: 12, color: 0x5ee6a8 }) },
  draw: (ctx) => {
    ctx.rect(4, 40, 150, 14, 0x2e222f)
    ctx.text(`tick ${ctx.sim.tick}   ${ctx.frame.paused ? 'paused' : 'running'}`, 8, 43, {
      color: 0xffffff,
      size: 8,
    })
  },
})

// core-input-gamepad: move a square with a controller
//
// Shows: keys() binds a standard pad's left stick and D-pad to the same sim command as the arrow keys; the stick
//   reads through a radial deadzone, eight ways; unplugging the pad in use pauses with "Reconnect your controller".
// Controls: the left stick or the D-pad (any standard-mapping controller), or the arrow keys
// Packages: @mcthaydt/automata, zod
// Difficulty: ★☆☆☆
// Tier: core
// Golden: 120
import {
  defineCommand,
  defineComponent,
  defineGame,
  definePlugin,
  defineSystem,
  keys,
  rect,
} from '@mcthaydt/automata'
import { z } from 'zod'

const Body = defineComponent('body', { x: 'f32', y: 'f32' })
const step = z.number().int().min(-1).max(1).default(0)
const Move = defineCommand('move', z.object({ x: step, y: step }))

// The sim sees the same command whichever device sent it, so a replay never needs to know.
const move = defineSystem('move', (ctx) => {
  for (const { payload } of ctx.commands.of(Move))
    for (const body of ctx.query(Body)) {
      const { x, y } = body.get(Body)
      body.set(Body, { x: x + payload.x * 2, y: y + payload.y * 2 })
    }
})

const square = definePlugin({ name: 'square', defs: [Body, Move, move] })

export default defineGame({
  id: 'core-input-gamepad',
  size: { width: 320, height: 180 },
  sim: {
    plugins: [square],
    seed: 1,
    setup: (sim) => {
      sim.spawn([[Body, { x: 160, y: 90 }]])
    },
  },
  input: keys(
    Move,
    { ArrowLeft: { x: -1 }, ArrowRight: { x: 1 }, ArrowUp: { y: -1 }, ArrowDown: { y: 1 } },
    {
      pad: { 14: { x: -1 }, 15: { x: 1 }, 12: { y: -1 }, 13: { y: 1 } },
      stick: { 'left-left': { x: -1 }, 'left-right': { x: 1 }, 'left-up': { y: -1 }, 'left-down': { y: 1 } },
    },
  ),
  views: { [Body.id]: rect({ w: 8, h: 8, color: 0x4fc3f7 }) },
})

// core-input-keys: move a square with the keyboard, a pad or touch
//
// Shows: keys() turns what is held on the keyboard, a standard pad's D-pad or the touch buttons into one sim
//   command per tick, the same command from each device; rect() draws an entity, interpolated.
// Controls: arrows or WASD, the D-pad, or the touch buttons
// Packages: @mcthaydt/automata, zod
// Difficulty: ★☆☆☆
// Tier: core
// Golden: 120
import {
  defineCommand,
  defineComponent,
  defineGame,
  definePlugin,
  defineSystem,
  keys,
  rect,
} from '@mcthaydt/automata'
import { z } from 'zod'

const Body = defineComponent('body', { x: 'f32', y: 'f32' })
const step = z.number().int().min(-1).max(1).default(0)
const Move = defineCommand('move', z.object({ x: step, y: step }))

// The sim only sees commands: the same commands replay to the same positions.
const move = defineSystem('move', (ctx) => {
  for (const { payload } of ctx.commands.of(Move))
    for (const body of ctx.query(Body)) {
      const { x, y } = body.get(Body)
      body.set(Body, { x: x + payload.x * 2, y: y + payload.y * 2 })
    }
})

const square = definePlugin({ name: 'square', defs: [Body, Move, move] })

export default defineGame({
  id: 'core-input-keys',
  size: { width: 320, height: 180 },
  sim: {
    plugins: [square],
    seed: 1,
    setup: (sim) => {
      sim.spawn([[Body, { x: 160, y: 90 }]])
    },
  },
  input: keys(
    Move,
    {
      ArrowLeft: { x: -1 },
      KeyA: { x: -1 },
      ArrowRight: { x: 1 },
      KeyD: { x: 1 },
      ArrowUp: { y: -1 },
      KeyW: { y: -1 },
      ArrowDown: { y: 1 },
      KeyS: { y: 1 },
    },
    { pad: { 14: { x: -1 }, 15: { x: 1 }, 12: { y: -1 }, 13: { y: 1 } } },
  ),
  views: { [Body.id]: rect({ w: 8, h: 8, color: 0xffc825 }) },
})

// core-input-rebind: rebind a control in Settings, and keep it next time
//
// Shows: keys() names each action with labels, so the default Settings screen (pause, then the gear) lists them;
//   rebinding one saves it through the host and play reads it at once; a key taken from another action leaves
//   that one "Unbound"; Escape cancels a capture. A reload keeps the player's keys.
// Controls: the arrows move, Space jumps, F fires; Escape or P to pause, then the gear for Settings
// Packages: @mcthaydt/automata, zod
// Difficulty: ★★☆☆
// Tier: core
// Golden: 120
import {
  defineCommand,
  defineComponent,
  defineGame,
  definePlugin,
  defineSystem,
  keys,
  rect,
} from '@mcthaydt/automata'
import { z } from 'zod'

const Runner = defineComponent('runner', { x: 'f32', y: 'f32', flash: 'f32' })
const step = z.number().int().min(-1).max(1).default(0)
const Act = defineCommand(
  'act',
  z.object({ x: step, jump: z.boolean().default(false), fire: z.boolean().default(false) }),
)

// Held, never pressed: the sim sees the same command whichever key the player bound to it.
const act = defineSystem('act', (ctx) => {
  for (const { payload } of ctx.commands.of(Act))
    for (const runner of ctx.query(Runner)) {
      const { x, y, flash } = runner.get(Runner)
      runner.set(Runner, {
        x: x + payload.x * 2,
        y: payload.jump ? Math.max(30, y - 3) : Math.min(140, y + 3),
        flash: payload.fire ? 1 : Math.max(0, flash - 0.125),
      })
    }
})

const runners = definePlugin({ name: 'runners', defs: [Runner, Act, act] })

export default defineGame({
  id: 'core-input-rebind',
  size: { width: 320, height: 180 },
  sim: {
    plugins: [runners],
    seed: 1,
    setup: (sim) => {
      sim.spawn([[Runner, { x: 160, y: 140, flash: 0 }]])
    },
  },
  input: keys(
    Act,
    { ArrowLeft: { x: -1 }, ArrowRight: { x: 1 }, Space: { jump: true }, KeyF: { fire: true } },
    {
      pad: { 14: { x: -1 }, 15: { x: 1 }, 0: { jump: true }, 2: { fire: true } },
      labels: { ArrowLeft: 'Move left', ArrowRight: 'Move right', Space: 'Jump', KeyF: 'Fire' },
    },
  ),
  views: { [Runner.id]: rect({ w: 10, h: 10, color: 0x5ac54f, anchor: { x: 0.5, y: 0.5 } }) },
})

// core-input-touch: steer a square by swiping, and flick down to drop it
//
// Shows: keys() gestures: a swipe holds a direction while the finger steers past a 12 px dead zone, a flick down
//   (40 px within 180 ms) lasts exactly one tick; with no touch buttons, the play screen takes touch as a swipe
//   surface. The arrows drive the same command.
// Controls: on a touch screen, swipe left or right and flick down; or the arrows to steer
// Packages: @mcthaydt/automata, zod
// Difficulty: ★★☆☆
// Tier: core
import {
  defineCommand,
  defineComponent,
  defineGame,
  definePlugin,
  defineSystem,
  keys,
  rect,
} from '@mcthaydt/automata'
import { z } from 'zod'

const Body = defineComponent('body', { x: 'f32', y: 'f32' })
const Steer = defineCommand(
  'steer',
  z.object({ x: z.number().int().min(-1).max(1).default(0), drop: z.boolean().default(false) }),
)

// A flick is one tick long, so `drop` moves the square one step down per flick.
const steer = defineSystem('steer', (ctx) => {
  for (const { payload } of ctx.commands.of(Steer))
    for (const body of ctx.query(Body)) {
      const { x, y } = body.get(Body)
      body.set(Body, { x: x + payload.x * 2, y: payload.drop ? (y + 20) % 180 : y })
    }
})

const square = definePlugin({ name: 'square', defs: [Body, Steer, steer] })

export default defineGame({
  id: 'core-input-touch',
  size: { width: 320, height: 180 },
  sim: {
    plugins: [square],
    seed: 1,
    setup: (sim) => {
      sim.spawn([[Body, { x: 160, y: 30 }]])
    },
  },
  input: keys(
    Steer,
    { ArrowLeft: { x: -1 }, ArrowRight: { x: 1 } },
    {
      touch: false,
      gestures: { 'swipe-left': { x: -1 }, 'swipe-right': { x: 1 }, 'flick-down': { drop: true } },
    },
  ),
  views: { [Body.id]: rect({ w: 8, h: 8, color: 0x0cf1ff }) },
})

// core-leaderboard: a run's score goes to the host's leaderboard, and paused shows the board
//
// Shows: `scores` maps a sim event to a board and a score: the score comes from the event's payload, so it is computed
//   from sim state and never typed by anyone. The game asks the host for leaderboards; pause to see the board the
//   host holds, with your row marked. Offline or standalone, paused says so and shows no board kept here.
// Controls: Escape or P to pause and see the board
// Packages: @mcthaydt/automata, zod
// Difficulty: ★★☆☆
// Tier: core
// Golden: 240
import {
  defineComponent,
  defineEvent,
  defineGame,
  definePlugin,
  defineSystem,
  rect,
} from '@mcthaydt/automata'
import { z } from 'zod'

const Runner = defineComponent('runner', { x: 'f32', y: 'f32', laps: 'f32' })
const RunEnded = defineEvent('run-ended', z.object({ score: z.number().int() }))

// A run lasts 120 ticks (two seconds). The runner crosses the field and wraps; each wrap is a lap, and a run's score
// is the laps it made times 100, plus the distance into the current lap.
const run = defineSystem('run', (ctx) => {
  for (const runner of ctx.query(Runner)) {
    const { x, y, laps } = runner.get(Runner)
    const next = x + 7
    const wrapped = next >= 320
    const nextLaps = wrapped ? laps + 1 : laps
    runner.set(Runner, { x: wrapped ? next - 320 : next, y, laps: nextLaps })
    if (ctx.tick % 120 === 119) {
      ctx.emit(RunEnded, { score: Math.floor(nextLaps * 100 + next / 4) })
      runner.set(Runner, { x: 0, y, laps: 0 })
    }
  }
})

const running = definePlugin({ name: 'running', defs: [Runner, RunEnded, run] })

export default defineGame({
  id: 'core-leaderboard',
  size: { width: 320, height: 180 },
  sim: {
    plugins: [running],
    seed: 1,
    setup: (sim) => {
      sim.spawn([[Runner, { x: 0, y: 90, laps: 0 }]])
    },
  },
  views: { [Runner.id]: rect({ w: 16, h: 16, color: 0x5ac54f, anchor: { x: 0.5, y: 0.5 } }) },
  scores: { [RunEnded.id]: { board: 'best', score: (payload) => RunEnded.schema.parse(payload).score } },
})

// core-saves: three save slots on the title, and progress kept while you play
//
// Shows: `saves` gives the game slots: the title lists them, New game writes the starting data to a slot, Continue
//   loads one and `apply`s it, and the game keeps the slot saved as you walk (leaving play, going to the background,
//   and when the host closes the game). Paused says what the host did with your progress, and offers Load newer or
//   Keep playing if another device changed this slot. Standalone, there is nothing to sync and nothing is said.
// Controls: arrows or WASD to walk; Escape or P to pause
// Packages: @mcthaydt/automata, zod
// Difficulty: ★★★☆
// Tier: core
// Golden: 120
import {
  defineCommand,
  defineComponent,
  defineGame,
  definePlugin,
  defineSave,
  defineSystem,
  type GameSaves,
  keys,
  rect,
  type Sim,
} from '@mcthaydt/automata'
import { z } from 'zod'

const Walker = defineComponent('walker', { x: 'f32', y: 'f32' })
const step = z.number().int().min(-1).max(1).default(0)
const Move = defineCommand('move', z.object({ x: step, y: step }))

const move = defineSystem('move', (ctx) => {
  for (const { payload } of ctx.commands.of(Move))
    for (const walker of ctx.query(Walker)) {
      const { x, y } = walker.get(Walker)
      walker.set(Walker, { x: x + payload.x * 2, y: y + payload.y * 2 })
    }
})

const walking = definePlugin({ name: 'walking', defs: [Walker, Move, move] })

// What a slot holds is plain data, never the sim: where the walker stands. A change to its shape is a new `version`
// with a migration that turns the old data into the new.
const Progress = z.object({ x: z.number(), y: z.number() })
type Progress = z.infer<typeof Progress>
const START: Progress = { x: 160, y: 90 }

const saves: GameSaves<Progress> = {
  def: defineSave({
    key: 'walk',
    version: 1,
    schema: Progress,
    empty: () => START,
    migrations: {},
    slots: { count: 3 },
  }),
  // Read from the live sim whenever a trigger writes; apply puts a loaded slot back before tick 0.
  capture: (sim: Sim) => {
    const walker = sim.query(Walker)[0]
    return walker === undefined ? START : walker.get(Walker)
  },
  apply: (sim: Sim, data: Progress) => {
    sim.query(Walker)[0]?.set(Walker, data)
  },
  label: (slot: number) => `Walk ${slot + 1}`,
}

export default defineGame({
  id: 'core-saves',
  size: { width: 320, height: 180 },
  sim: {
    plugins: [walking],
    seed: 1,
    setup: (sim) => {
      sim.spawn([[Walker, START]])
    },
  },
  input: keys(Move, {
    ArrowLeft: { x: -1 },
    KeyA: { x: -1 },
    ArrowRight: { x: 1 },
    KeyD: { x: 1 },
    ArrowUp: { y: -1 },
    KeyW: { y: -1 },
    ArrowDown: { y: 1 },
    KeyS: { y: 1 },
  }),
  views: { [Walker.id]: rect({ w: 8, h: 8, color: 0xffc825 }) },
  saves,
})

// render-filter: two screen-space filters over the picture, and the quality tier that decides which run
//
// Shows: postFilter(name, { glsl, wgsl }) declares a filter over the whole picture, once for WebGL2 and once for
//   WebGPU, so both renderers look the same. `dusk` warms the picture and darkens its corners at every tier.
//   `scanlines` darkens every second row, runs after `dusk` (order) and only from the medium tier up (minTier),
//   so the HUD, which lists the filters running now, loses it at low and gets it back at medium.
// Controls: 1 low, 2 medium, 3 high
// Packages: @mcthaydt/automata
// Difficulty: ★★★☆
// Tier: core
import { defineComponent, defineGame, definePlugin, defineSystem, postFilter, rect } from '@mcthaydt/automata'

const Drift = defineComponent('drift', { x: 'f32', y: 'f32', vx: 'f32' })

const drift = defineSystem('drift', (ctx) => {
  for (const square of ctx.query(Drift)) {
    const { x, y, vx } = square.get(Drift)
    square.set(Drift, { x: x + vx > 324 ? -4 : x + vx, y, vx })
  }
})

const squares = definePlugin({ name: 'squares', defs: [Drift, drift] })

// A fragment shader reads the picture as `uTexture` at `vTextureCoord` (GLSL) or `input.uv` (WGSL), 0 to 1 across it.
const dusk = postFilter('dusk', {
  glsl: `in vec2 vTextureCoord;
out vec4 finalColor;
uniform sampler2D uTexture;
void main() {
  vec2 away = vTextureCoord - 0.5;
  finalColor = vec4(texture(uTexture, vTextureCoord).rgb * vec3(1.0, 0.85, 0.7) * (1.0 - dot(away, away) * 1.4), 1.0);
}`,
  wgsl: `@fragment fn mainFragment(input: VSOutput) -> @location(0) vec4<f32> {
  let away = input.uv - vec2<f32>(0.5);
  return vec4<f32>(textureSample(uTexture, uSampler, input.uv).rgb * vec3<f32>(1.0, 0.85, 0.7) * (1.0 - dot(away, away) * 1.4), 1.0);
}`,
})

// 180 is the playfield's height, so a row of the filter is a row of the game's pixels.
const scanlines = postFilter('scanlines', {
  glsl: `in vec2 vTextureCoord;
out vec4 finalColor;
uniform sampler2D uTexture;
void main() {
  float odd = mod(floor(vTextureCoord.y * 180.0), 2.0);
  finalColor = vec4(texture(uTexture, vTextureCoord).rgb * (1.0 - 0.3 * odd), 1.0);
}`,
  wgsl: `@fragment fn mainFragment(input: VSOutput) -> @location(0) vec4<f32> {
  let odd = floor(input.uv.y * 180.0) % 2.0;
  return vec4<f32>(textureSample(uTexture, uSampler, input.uv).rgb * (1.0 - 0.3 * odd), 1.0);
}`,
  order: 1,
  minTier: 'medium',
})

const TIER_KEYS = { Digit1: 'low', Digit2: 'medium', Digit3: 'high' } as const

// What the HUD reads from the stage that setup receives.
let stage: { readonly quality: string; readonly postFilters: { readonly ids: readonly string[] } } | undefined

export default defineGame({
  id: 'render-filter',
  size: { width: 320, height: 180 },
  sim: {
    plugins: [squares],
    seed: 1,
    setup: (sim) => {
      for (let row = 0; row < 5; row += 1)
        sim.spawn([[Drift, { x: row * 60, y: 50 + row * 24, vx: 0.5 + row * 0.25 }]])
    },
  },
  views: { [Drift.id]: rect({ w: 12, h: 12, color: 0xf9c22b }) },
  renderer: {
    postFilters: [dusk, scanlines],
    // The tier is presentation: it never reaches the sim, so the keys go straight to the stage.
    setup: (pixi) => {
      stage = pixi
      const pick = (event: KeyboardEvent): void => {
        // Pixi drops the renderer when the game is torn down; the listener then removes itself.
        if (!pixi.app.renderer) window.removeEventListener('keydown', pick)
        else if (event.code in TIER_KEYS) pixi.setQuality(TIER_KEYS[event.code as keyof typeof TIER_KEYS])
      }
      window.addEventListener('keydown', pick)
    },
  },
  draw: (ctx) => {
    if (stage === undefined) return
    ctx.rect(4, 40, 200, 14, 0x2e222f)
    ctx.text(`quality ${stage.quality}   filters ${stage.postFilters.ids.join(' ')}`, 8, 43, {
      color: 0xffffff,
      size: 8,
    })
  },
})

// render-interpolation: a square drawn between sim ticks, beside a line where the sim says it is
//
// Shows: a view draws the blend of the last two ticks by the frame's alpha (0 is the previous tick, 1 the
//   current one), so motion stays smooth when display frames and sim ticks do not line up. The pink line is the
//   sim's own position, which only moves a whole tick at a time; the HUD prints the frame's alpha.
// Controls: I turns the blend on and off
// Packages: @mcthaydt/automata
// Difficulty: ★★☆☆
// Tier: core
import { defineComponent, defineGame, definePlugin, defineSystem, rect } from '@mcthaydt/automata'

const Runner = defineComponent('runner', { x: 'f32', y: 'f32', vx: 'f32' })

// 5 px a tick is a step the eye can see, so the blend's smoothing shows. The runner turns at either edge.
const run = defineSystem('run', (ctx) => {
  for (const runner of ctx.query(Runner)) {
    const { x, y, vx } = runner.get(Runner)
    const next = x + vx < 8 || x + vx > 312 ? -vx : vx
    runner.set(Runner, { x: x + next, y, vx: next })
  }
})

const track = definePlugin({ name: 'track', defs: [Runner, run] })

// Presentation only: whether the view blends between ticks. It never reaches the sim.
let blend = true
const square = rect({ w: 12, h: 12, color: 0xf9c22b })

// The view's own `update` gets the frame's alpha; asking for 1 shows the current tick as it is.
const blended: typeof square = (row, componentId) => {
  const view = square(row, componentId)
  if (view?.update === undefined) return view
  const place = view.update.bind(view)
  return { ...view, update: (curr, prev, alpha) => place(curr, prev, blend ? alpha : 1) }
}

export default defineGame({
  id: 'render-interpolation',
  size: { width: 320, height: 180 },
  sim: {
    plugins: [track],
    seed: 1,
    setup: (sim) => void sim.spawn([[Runner, { x: 8, y: 90, vx: 5 }]]),
  },
  views: { [Runner.id]: blended },
  renderer: {
    setup: (stage) => {
      const toggle = (event: KeyboardEvent): void => {
        // Pixi drops the renderer when the game is torn down; the listener then removes itself.
        if (!stage.app.renderer) window.removeEventListener('keydown', toggle)
        else if (event.code === 'KeyI') blend = !blend
      }
      window.addEventListener('keydown', toggle)
    },
  },
  draw: (ctx) => {
    for (const runner of ctx.sim.query(Runner)) {
      const { x, y } = runner.get(Runner)
      ctx.line(x, y - 14, x, y + 14, 0xff5d8f, 1)
    }
    ctx.rect(4, 40, 150, 14, 0x2e222f)
    ctx.text(`blend ${blend ? 'on' : 'off'}   alpha ${ctx.frame.alpha.toFixed(2)}`, 8, 43, {
      color: 0xffffff,
      size: 8,
    })
  },
})

// render-quality: switch the graphics quality tier while squares drift across the field
//
// Shows: stage.setQuality() changes the tier at run time: it caps the canvas resolution (low 1, medium 1.5,
//   high 2) and leaves out post filters registered with a higher minTier. The world and HUD draw through the
//   fixed-resolution composite, so pixel art stays whole-pixel at every tier.
// Controls: 1 low, 2 medium, 3 high
// Packages: @mcthaydt/automata
// Difficulty: ★★☆☆
// Tier: core
import { defineComponent, defineGame, definePlugin, defineSystem, rect } from '@mcthaydt/automata'

const Drift = defineComponent('drift', { x: 'f32', y: 'f32', vx: 'f32' })

// Each square drifts right and wraps, so the tier's effect on the edges shows while it moves.
const drift = defineSystem('drift', (ctx) => {
  for (const square of ctx.query(Drift)) {
    const { x, y, vx } = square.get(Drift)
    square.set(Drift, { x: x + vx > 324 ? -4 : x + vx, y, vx })
  }
})

const squares = definePlugin({ name: 'squares', defs: [Drift, drift] })

const TIER_KEYS = { Digit1: 'low', Digit2: 'medium', Digit3: 'high' } as const

// What the HUD reads from the stage that setup receives.
let stage:
  | { readonly quality: string; readonly app: { readonly renderer: { readonly resolution: number } } }
  | undefined

export default defineGame({
  id: 'render-quality',
  size: { width: 320, height: 180 },
  sim: {
    plugins: [squares],
    seed: 1,
    setup: (sim) => {
      for (let row = 0; row < 5; row += 1)
        sim.spawn([[Drift, { x: row * 60, y: 40 + row * 24, vx: 0.5 + row * 0.25 }]])
    },
  },
  views: { [Drift.id]: rect({ w: 12, h: 12, color: 0xf9c22b }) },
  renderer: {
    // The tier is presentation: it never reaches the sim, so the keys go straight to the stage.
    setup: (pixi) => {
      stage = pixi
      const pick = (event: KeyboardEvent): void => {
        // Pixi drops the renderer when the game is torn down; the listener then removes itself.
        if (!pixi.app.renderer) {
          window.removeEventListener('keydown', pick)
          return
        }
        const tier = TIER_KEYS[event.code as keyof typeof TIER_KEYS]
        if (tier !== undefined) pixi.setQuality(tier)
      }
      window.addEventListener('keydown', pick)
    },
  },
  draw: (ctx) => {
    if (stage === undefined) return
    // y = 40: a wide phone shows only the band between about y = 35 and y = 145 of the 180-high field.
    ctx.rect(4, 40, 168, 14, 0x2e222f)
    ctx.text(`quality ${stage.quality}   resolution ${stage.app.renderer.resolution}`, 8, 43, {
      color: 0xffffff,
      size: 8,
    })
  },
})

// shapes-draw-hud: a HUD and a mini-map drawn each frame over bouncing squares
//
// Shows: draw(ctx) paints rects, lines, circles and text over the entity views once a frame. It reads the
//   sim through ctx.sim and never writes it, so the golden is the same with or without it.
// Controls: none
// Packages: @mcthaydt/automata
// Difficulty: ★☆☆☆
// Tier: core
// Golden: 120
import { defineComponent, defineGame, definePlugin, defineSystem, rect } from '@mcthaydt/automata'

const Ball = defineComponent('ball', { x: 'f32', y: 'f32', vx: 'f32', vy: 'f32' })

// Each square moves by its velocity and turns back at the playfield's edges.
const bounce = defineSystem('bounce', (ctx) => {
  for (const ball of ctx.query(Ball)) {
    const { x, y, vx, vy } = ball.get(Ball)
    const nextVx = x + vx < 4 || x + vx > 316 ? -vx : vx
    const nextVy = y + vy < 20 || y + vy > 176 ? -vy : vy
    ball.set(Ball, { x: x + nextVx, y: y + nextVy, vx: nextVx, vy: nextVy })
  }
})

const balls = definePlugin({ name: 'balls', defs: [Ball, bounce] })

// The mini-map: the whole playfield scaled into a box at the bottom left of the band a wide phone shows (about
// y = 35 to y = 145 of the 180-high field), clear of the Pause button.
const MAP = { x: 8, y: 104, w: 64, h: 36 }

export default defineGame({
  id: 'shapes-draw-hud',
  size: { width: 320, height: 180 },
  sim: {
    plugins: [balls],
    seed: 1,
    setup: (sim) => {
      sim.spawn([[Ball, { x: 40, y: 60, vx: 1.5, vy: 1 }]])
      sim.spawn([[Ball, { x: 160, y: 120, vx: -2, vy: 0.5 }]])
      sim.spawn([[Ball, { x: 280, y: 90, vx: 1, vy: -1.5 }]])
    },
  },
  views: { [Ball.id]: rect({ w: 8, h: 8, color: 0x00cdf9 }) },
  draw: (ctx) => {
    const all = ctx.sim.query(Ball)
    ctx.rect(200, 126, 112, 14, 0x2e222f)
    ctx.text(`tick ${ctx.sim.tick}   squares ${all.length}`, 204, 129, { color: 0xffffff, size: 8 })

    const { x, y, w, h } = MAP
    ctx.rect(x, y, w, h, 0x3e3546)
    ctx.line(x, y, x + w, y, 0xffffff)
    ctx.line(x, y + h, x + w, y + h, 0xffffff)
    ctx.line(x, y, x, y + h, 0xffffff)
    ctx.line(x + w, y, x + w, y + h, 0xffffff)
    for (const ball of all) {
      const at = ball.get(Ball)
      ctx.circle(x + (at.x / ctx.width) * w, y + (at.y / ctx.height) * h, 1.5, 0xf9c22b)
    }
  },
})

// shapes-rects: rectangles that move, slide and spin
//
// Shows: rect() draws one view per component id, interpolated between ticks: position, an anchor,
//   and an angle that turns along the shorter arc.
// Controls: none
// Packages: @mcthaydt/automata
// Difficulty: ★☆☆☆
// Tier: core
// Golden: 120
import { defineComponent, defineGame, definePlugin, defineSystem, rect } from '@mcthaydt/automata'

const Block = defineComponent('block', { x: 'f32', y: 'f32' })
const Bar = defineComponent('bar', { x: 'f32', y: 'f32' })
const Spinner = defineComponent('spinner', { x: 'f32', y: 'f32', angle: 'f32' })

// Blocks fall and wrap; the bar slides right and wraps; the spinner turns a little each tick.
const move = defineSystem('move', (ctx) => {
  for (const block of ctx.query(Block)) {
    const { y } = block.get(Block)
    block.set(Block, { y: y > 196 ? -16 : y + 1 })
  }
  for (const bar of ctx.query(Bar)) {
    const { x } = bar.get(Bar)
    bar.set(Bar, { x: x > 320 ? -64 : x + 2 })
  }
  for (const spinner of ctx.query(Spinner)) {
    const { angle } = spinner.get(Spinner)
    spinner.set(Spinner, { angle: angle + 0.05 })
  }
})

const shapes = definePlugin({ name: 'shapes', defs: [Block, Bar, Spinner, move] })

export default defineGame({
  id: 'shapes-rects',
  size: { width: 320, height: 180 },
  sim: {
    plugins: [shapes],
    seed: 1,
    setup: (sim) => {
      for (let column = 0; column < 4; column++) sim.spawn([[Block, { x: 40 + column * 32, y: column * 40 }]])
      sim.spawn([[Bar, { x: 0, y: 150 }]])
      sim.spawn([[Spinner, { x: 240, y: 70, angle: 0 }]])
    },
  },
  views: {
    [Block.id]: rect({ w: 16, h: 16, color: 0x00cdf9 }),
    // Anchored at its left edge, so x is where the bar starts.
    [Bar.id]: rect({ w: 64, h: 6, color: 0x5ac54f, anchor: { x: 0, y: 0.5 } }),
    [Spinner.id]: rect({ w: 48, h: 12, color: 0xf5555d }),
  },
})

// textures-atlas: sprites drawn from a packed atlas
//
// Shows: sprite(url, { frame }) draws one named frame of a texture atlas that `automata-content assets` packed
//   from a folder of PNG frames; each frame keeps its own name, so art can be repacked without touching code.
// Controls: none
// Packages: @mcthaydt/automata
// Difficulty: ★★☆☆
// Tier: core
// Golden: 120
import { defineComponent, defineGame, definePlugin, defineSystem, sprite } from '@mcthaydt/automata'

// Wick's two run frames, packed by content/atlases.toml into an atlas page served beside this page
// (public/textures/atlas/; the frames' provenance is resources/atlas-frames/PROVENANCE.md).
const atlas = 'wick-0.json'

// One component per frame, so each view shows its own named frame.
const StrideA = defineComponent('stride-a', { x: 'f32', y: 'f32' })
const StrideB = defineComponent('stride-b', { x: 'f32', y: 'f32' })

// Both Wicks run right one pixel a tick and wrap at the edge.
const run = defineSystem('run', (ctx) => {
  for (const kind of [StrideA, StrideB]) {
    for (const runner of ctx.query(kind)) {
      const { x } = runner.get(kind)
      runner.set(kind, { x: x > 328 ? -8 : x + 1 })
    }
  }
})

const runners = definePlugin({ name: 'runners', defs: [StrideA, StrideB, run] })

export default defineGame({
  id: 'textures-atlas',
  size: { width: 320, height: 180 },
  sim: {
    plugins: [runners],
    seed: 1,
    setup: (sim) => {
      sim.spawn([[StrideA, { x: 120, y: 90 }]])
      sim.spawn([[StrideB, { x: 200, y: 90 }]])
    },
  },
  views: {
    [StrideA.id]: sprite(atlas, { frame: 'run-a' }),
    [StrideB.id]: sprite(atlas, { frame: 'run-b' }),
  },
})

// textures-sprite: an animated sprite from a sprite sheet
//
// Shows: sprite() draws a texture by url, interpolated like rect(); `frames` slices a sheet into
//   equal frames and the component's `frame` field picks one each tick.
// Controls: none
// Packages: @mcthaydt/automata
// Difficulty: ★★☆☆
// Tier: core
// Golden: 120
import { defineComponent, defineGame, definePlugin, defineSystem, sprite } from '@mcthaydt/automata'

// Two 16 × 16 frames of Wick running (resources/sprites/PROVENANCE.md).
const sheet = new URL('../resources/sprites/wick-run.png', import.meta.url).href

const Runner = defineComponent('runner', { x: 'f32', y: 'f32', frame: 'i32' })

// Run right one pixel a tick, wrap at the edge, and switch frames every 8 ticks.
const run = defineSystem('run', (ctx) => {
  for (const runner of ctx.query(Runner)) {
    const { x } = runner.get(Runner)
    runner.set(Runner, { x: x > 328 ? -8 : x + 1, frame: Math.floor(ctx.tick / 8) })
  }
})

const runners = definePlugin({ name: 'runners', defs: [Runner, run] })

export default defineGame({
  id: 'textures-sprite',
  size: { width: 320, height: 180 },
  sim: {
    plugins: [runners],
    seed: 1,
    setup: (sim) => {
      sim.spawn([[Runner, { x: 160, y: 90, frame: 0 }]])
    },
  },
  views: { [Runner.id]: sprite(sheet, { frames: { width: 16, height: 16 } }) },
})
